import math

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def is_power_of_2_or_5(num):
    if num == 0:
        return False # D(n) should be positive for n>=0

    # Divide out factors of 2
    while num % 2 == 0:
        num //= 2

    # Divide out factors of 5
    while num % 5 == 0:
        num //= 5

    return num == 1

# Test values for n: 0 <= n <= 20 and n % 3 != 1
n_values = [n for n in range(21) if n % 3 != 1]

results = []

for n in n_values:
    Dn = D(n)
    is_valid = is_power_of_2_or_5(Dn)

    # Get prime factorization for logging purposes (only if not 2^a 5^b)
    factors = {}
    temp_Dn = Dn
    d = 2
    while d * d <= temp_Dn:
        while temp_Dn % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_Dn //= d
        d += 1
    if temp_Dn > 1:
        factors[temp_Dn] = factors.get(temp_Dn, 0) + 1

    result_str = {
        'n': n,
        'D(n)': Dn,
        'is_valid': is_valid,
        'factors': factors
    }
    results.append(result_str)

print("--- Results ---")
for res in results:
    print(f"n={res['n']}: D(n)={res['D(n)']}. Valid 2^a 5^b? {res['is_valid']}. Factors: {res['factors']}")

